CREATE TABLE "${primehrSchema}".ld_governance_policy (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uk_ld_policy_code UNIQUE(agency_id,normalized_code));
CREATE TABLE "${primehrSchema}".ld_governance_policy_version (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,policy_id VARCHAR(36) NOT NULL,definition_version INTEGER NOT NULL,supersedes_id VARCHAR(36),title VARCHAR(200) NOT NULL,description VARCHAR(2000),legal_basis VARCHAR(1000) NOT NULL,planning_year_start_month INTEGER NOT NULL,minimum_planned_interventions INTEGER NOT NULL,supervisory_minimum_hours NUMERIC(10,2) NOT NULL,behavior_evaluation_min_days INTEGER NOT NULL,behavior_evaluation_max_days INTEGER NOT NULL,requires_idp BOOLEAN NOT NULL,requires_supervisor_recommendation BOOLEAN NOT NULL,requires_final_approval BOOLEAN NOT NULL,status VARCHAR(20) NOT NULL,effective_from DATE,effective_to DATE,published_by VARCHAR(100),published_at TIMESTAMP WITH TIME ZONE,retired_by VARCHAR(100),retired_at TIMESTAMP WITH TIME ZONE,retirement_reason VARCHAR(1000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_ld_policy_version_policy FOREIGN KEY(policy_id) REFERENCES "${primehrSchema}".ld_governance_policy(id),CONSTRAINT fk_ld_policy_version_prior FOREIGN KEY(supersedes_id) REFERENCES "${primehrSchema}".ld_governance_policy_version(id),CONSTRAINT uk_ld_policy_version UNIQUE(agency_id,policy_id,definition_version),CONSTRAINT ck_ld_policy_version_number CHECK(definition_version>=1),CONSTRAINT ck_ld_policy_month CHECK(planning_year_start_month BETWEEN 1 AND 12),CONSTRAINT ck_ld_policy_minimum CHECK(minimum_planned_interventions>=0 AND supervisory_minimum_hours>=0),CONSTRAINT ck_ld_policy_behavior_days CHECK(behavior_evaluation_min_days>=0 AND behavior_evaluation_max_days>=behavior_evaluation_min_days),CONSTRAINT ck_ld_policy_status CHECK(status IN ('DRAFT','PUBLISHED','RETIRED')),CONSTRAINT ck_ld_policy_dates CHECK(effective_to IS NULL OR effective_from IS NULL OR effective_to>=effective_from),CONSTRAINT ck_ld_policy_lifecycle CHECK((status='DRAFT' AND effective_from IS NULL AND published_by IS NULL AND published_at IS NULL) OR (status IN ('PUBLISHED','RETIRED') AND effective_from IS NOT NULL AND published_by IS NOT NULL AND published_at IS NOT NULL)));
CREATE INDEX ix_ld_policy_effective ON "${primehrSchema}".ld_governance_policy_version(agency_id,status,effective_from,effective_to);

CREATE TABLE "${primehrSchema}".ld_intervention (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uk_ld_intervention_code UNIQUE(agency_id,normalized_code));
CREATE TABLE "${primehrSchema}".ld_intervention_version (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,intervention_id VARCHAR(36) NOT NULL,definition_version INTEGER NOT NULL,supersedes_id VARCHAR(36),title VARCHAR(200) NOT NULL,description VARCHAR(2000),category VARCHAR(30) NOT NULL,default_modality VARCHAR(30) NOT NULL,intended_outcomes VARCHAR(3000) NOT NULL,delivery_requirements VARCHAR(3000),status VARCHAR(20) NOT NULL,effective_from DATE,effective_to DATE,published_by VARCHAR(100),published_at TIMESTAMP WITH TIME ZONE,retired_by VARCHAR(100),retired_at TIMESTAMP WITH TIME ZONE,retirement_reason VARCHAR(1000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_ld_intervention_version_root FOREIGN KEY(intervention_id) REFERENCES "${primehrSchema}".ld_intervention(id),CONSTRAINT fk_ld_intervention_version_prior FOREIGN KEY(supersedes_id) REFERENCES "${primehrSchema}".ld_intervention_version(id),CONSTRAINT uk_ld_intervention_version UNIQUE(agency_id,intervention_id,definition_version),CONSTRAINT ck_ld_intervention_version_number CHECK(definition_version>=1),CONSTRAINT ck_ld_intervention_category CHECK(category IN ('CLASSROOM','ONLINE_BLENDED','COACHING','MENTORING','JOB_ROTATION','JOB_SHADOWING','SELF_DEVELOPMENT','SCHOLARSHIP','SPECIAL_PROJECT','KNOWLEDGE_SHARING','OTHER')),CONSTRAINT ck_ld_intervention_modality CHECK(default_modality IN ('IN_PERSON','ONLINE','BLENDED','WORKPLACE','SELF_DIRECTED','OTHER')),CONSTRAINT ck_ld_intervention_status CHECK(status IN ('DRAFT','PUBLISHED','RETIRED')),CONSTRAINT ck_ld_intervention_dates CHECK(effective_to IS NULL OR effective_from IS NULL OR effective_to>=effective_from),CONSTRAINT ck_ld_intervention_lifecycle CHECK((status='DRAFT' AND effective_from IS NULL AND published_by IS NULL AND published_at IS NULL) OR (status IN ('PUBLISHED','RETIRED') AND effective_from IS NOT NULL AND published_by IS NOT NULL AND published_at IS NOT NULL)));
CREATE INDEX ix_ld_intervention_effective ON "${primehrSchema}".ld_intervention_version(agency_id,intervention_id,status,effective_from,effective_to);

CREATE TABLE "${primehrSchema}".ld_provider (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,name VARCHAR(250) NOT NULL,provider_type VARCHAR(30) NOT NULL,accreditation_reference VARCHAR(500),contact_details VARCHAR(1000),status VARCHAR(20) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uk_ld_provider_code UNIQUE(agency_id,normalized_code),CONSTRAINT ck_ld_provider_type CHECK(provider_type IN ('INTERNAL_GOVERNMENT','EXTERNAL_GOVERNMENT','ACADEMIC','PROFESSIONAL','PRIVATE','INTERNATIONAL','OTHER')),CONSTRAINT ck_ld_provider_status CHECK(status IN ('ACTIVE','INACTIVE')));
CREATE INDEX ix_ld_provider_status ON "${primehrSchema}".ld_provider(agency_id,status,name);
CREATE TABLE "${primehrSchema}".ld_resource_person (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,person_source VARCHAR(20) NOT NULL,employee_no VARCHAR(100),display_name VARCHAR(250) NOT NULL,provider_id VARCHAR(36),expertise VARCHAR(2000),credentials VARCHAR(2000),contact_details VARCHAR(1000),status VARCHAR(20) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_ld_resource_person_provider FOREIGN KEY(provider_id) REFERENCES "${primehrSchema}".ld_provider(id),CONSTRAINT uk_ld_resource_person_code UNIQUE(agency_id,normalized_code),CONSTRAINT ck_ld_resource_person_source CHECK(person_source IN ('EMPLOYEE','EXTERNAL')),CONSTRAINT ck_ld_resource_person_employee CHECK((person_source='EMPLOYEE' AND employee_no IS NOT NULL) OR (person_source='EXTERNAL' AND employee_no IS NULL)),CONSTRAINT ck_ld_resource_person_status CHECK(status IN ('ACTIVE','INACTIVE')));
CREATE INDEX ix_ld_resource_person_status ON "${primehrSchema}".ld_resource_person(agency_id,status,display_name);

CREATE TABLE "${primehrSchema}".ld_evaluation_framework (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uk_ld_evaluation_framework_code UNIQUE(agency_id,normalized_code));
CREATE TABLE "${primehrSchema}".ld_evaluation_framework_version (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,framework_id VARCHAR(36) NOT NULL,definition_version INTEGER NOT NULL,supersedes_id VARCHAR(36),title VARCHAR(200) NOT NULL,description VARCHAR(2000),legal_basis VARCHAR(1000) NOT NULL,level_revision INTEGER NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL,effective_from DATE,effective_to DATE,published_by VARCHAR(100),published_at TIMESTAMP WITH TIME ZONE,retired_by VARCHAR(100),retired_at TIMESTAMP WITH TIME ZONE,retirement_reason VARCHAR(1000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_ld_eval_framework_root FOREIGN KEY(framework_id) REFERENCES "${primehrSchema}".ld_evaluation_framework(id),CONSTRAINT fk_ld_eval_framework_prior FOREIGN KEY(supersedes_id) REFERENCES "${primehrSchema}".ld_evaluation_framework_version(id),CONSTRAINT uk_ld_evaluation_framework_version UNIQUE(agency_id,framework_id,definition_version),CONSTRAINT ck_ld_eval_framework_version_number CHECK(definition_version>=1),CONSTRAINT ck_ld_eval_framework_status CHECK(status IN ('DRAFT','PUBLISHED','RETIRED')),CONSTRAINT ck_ld_eval_framework_dates CHECK(effective_to IS NULL OR effective_from IS NULL OR effective_to>=effective_from),CONSTRAINT ck_ld_eval_framework_lifecycle CHECK((status='DRAFT' AND effective_from IS NULL AND published_by IS NULL AND published_at IS NULL) OR (status IN ('PUBLISHED','RETIRED') AND effective_from IS NOT NULL AND published_by IS NOT NULL AND published_at IS NOT NULL)));
CREATE INDEX ix_ld_evaluation_effective ON "${primehrSchema}".ld_evaluation_framework_version(agency_id,framework_id,status,effective_from,effective_to);
CREATE TABLE "${primehrSchema}".ld_evaluation_level (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,framework_version_id VARCHAR(36) NOT NULL,level_type VARCHAR(30) NOT NULL,required BOOLEAN NOT NULL,due_after_days INTEGER NOT NULL,score_method VARCHAR(20) NOT NULL,passing_score NUMERIC(19,6),evidence_requirements VARCHAR(3000) NOT NULL,instrument_guidance VARCHAR(3000) NOT NULL,display_order INTEGER NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_ld_evaluation_level_version FOREIGN KEY(framework_version_id) REFERENCES "${primehrSchema}".ld_evaluation_framework_version(id),CONSTRAINT uk_ld_evaluation_level_type UNIQUE(agency_id,framework_version_id,level_type),CONSTRAINT uk_ld_evaluation_level_order UNIQUE(agency_id,framework_version_id,display_order),CONSTRAINT ck_ld_evaluation_level_type CHECK(level_type IN ('REACTION','LEARNING','BEHAVIOR_APPLICATION','RESULTS','RETURN_OF_EXPECTATION')),CONSTRAINT ck_ld_evaluation_score_method CHECK(score_method IN ('QUALITATIVE','PERCENTAGE','POINTS','PASS_FAIL')),CONSTRAINT ck_ld_evaluation_due CHECK(due_after_days>=0 AND display_order>=1),CONSTRAINT ck_ld_evaluation_passing CHECK(passing_score IS NULL OR passing_score>=0));
CREATE INDEX ix_ld_evaluation_level ON "${primehrSchema}".ld_evaluation_level(agency_id,framework_version_id,display_order);
